const translations: Record<Language, AccountSettingsText> = { en, km, id, lo, my, th, fil };

const localeByLanguage: Record<Language, string> = {
  en: 'en-US',
  km: 'km-KH',
  id: 'id-ID',
  lo: 'lo-LA',
  my: 'my-MM',
  th: 'th-TH',
  fil: 'fil-PH',
};

function interpolate(template: string, values: TemplateValues = {}): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (
    key in values ? String(values[key]) : match
  ));
}

export type AccountSettingsCopy = {
  language: Language;
  locale: string;
  t: (key: keyof AccountSettingsText, values?: TemplateValues) => string;
};

export function getAccountSettingsCopy(language: Language): AccountSettingsCopy {
  const text = translations[language];
  return {
    language,
    locale: localeByLanguage[language],
    t: (key, values) => interpolate(text[key], values),
  };
}

export function formatAccountSettingsDate(
  language: Language,
  value: string | null | undefined,
  fallback: string,
  options: Intl.DateTimeFormatOptions = { dateStyle: 'medium', timeStyle: 'short' },
): string {
  if (!value) return fallback;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return fallback;
  return new Intl.DateTimeFormat(localeByLanguage[language], options).format(date);
}

export function accountSettingsErrorMessage(
  error: unknown,
  copy: AccountSettingsCopy,
  fallbackKey: keyof AccountSettingsText,
): string {
  switch (settingsErrorKind(error)) {
    case 'auth': return copy.t('errorAuth');
    case 'permission': return copy.t('errorPermission');
    case 'account-disabled': return copy.t('errorAccountDisabled');
    case 'rate-limit': return copy.t('errorRateLimit');
    case 'network': return copy.t('errorNetwork');
    case 'server':
    case 'request':
    case 'unknown':
    default: return copy.t(fallbackKey) || copy.t('errorGeneric');
  }
}

export { translations as accountSettingsTranslations };
